<script setup>import {cart,cartTotal,removeFromCart} from '../../stores';import {RouterLink} from 'vue-router'</script><template><section><h1 class="text-3xl font-black">Your cart</h1><div v-if="!cart.items.length" class="mt-8 rounded-2xl border bg-white p-10 text-center">Your cart is empty. <RouterLink class="font-bold text-indigo-600" to="/shop">Continue shopping</RouterLink></div><div v-else class="mt-8 grid gap-6 lg:grid-cols-[1fr_360px]"><div class="space-y-3"><div v-for="i in cart.items" :key="i.productId" class="flex items-center gap-4 rounded-2xl border bg-white p-4"><div class="h-20 w-20 rounded-xl bg-slate-100"><img v-if="i.imageUrl" :src="i.imageUrl" class="h-full w-full rounded-xl object-cover"/></div><div class="flex-1"><b>{{i.name}}</b><p class="text-sm text-slate-500">{{i.quantity}} × {{Number(i.price).toLocaleString()}} ETB</p></div><button @click="removeFromCart(i.productId)" class="text-sm font-semibold text-red-600">Remove</button></div></div><aside class="h-fit rounded-2xl border bg-white p-6"><p class="text-slate-500">Subtotal</p><p class="mt-2 text-3xl font-black">{{cartTotal.toLocaleString()}} ETB</p><RouterLink to="/checkout" class="mt-5 block rounded-xl bg-slate-950 py-3 text-center font-bold text-white">Checkout</RouterLink></aside></div></section></template>